<?php
declare(strict_types=1);
/** Canonical shared Local/Public Staff dashboard presentation. Hosts own data adapters only. */
if(!isset($dashE,$dashUrl,$dashIcon,$dashFaNum,$dashDegraded,$dashClock,$dashNotificationIcon,$dashMoney,$dashUnit)){throw new RuntimeException('Dashboard presenter helpers are missing.');}
?>
<section class="sc-dashboard sc-dashboard--converged" aria-label="داشبورد مدیریتی">
  <?php if($metrics): ?>
  <div class="sc-dashboard-kpis" aria-label="شاخص‌های امروز">
    <?php foreach($metrics as $metric): $delta=$metric['delta']; ?>
    <a class="sc-card sc-dashboard-kpi sc-dashboard-kpi--link" data-tone="<?=$dashE((string)$metric['tone'])?>" href="<?=$dashUrl((string)$metric['href'])?>" aria-label="<?=$dashE((string)$metric['label'])?>؛ مشاهده جزئیات"><span class="sc-dashboard-kpi__icon"><?=$dashIcon((string)$metric['icon'])?></span><div><small><?=$dashE((string)$metric['label'])?></small><strong><?=$dashE((string)$metric['value'])?></strong><?php if(is_int($delta)): ?><span class="sc-dashboard-kpi__delta <?=$delta>=0?'is-up':'is-down'?>"><?=$delta>=0?'↑':'↓'?> <?=$dashFaNum(abs($delta))?>٪ <?=$dashE((string)$metric['helper'])?></span><?php else: ?><span><?=$dashE((string)$metric['helper'])?></span><?php endif; ?></div><span class="sc-dashboard-chevron" aria-hidden="true"><?=$dashIcon('chevron-left')?></span></a>
    <?php endforeach; ?>
  </div>
  <?php endif; ?>

  <div class="sc-dashboard-main<?=$canReports?'':' is-compact'?>">
    <?php if($canReports): ?>
    <section class="sc-card sc-dashboard-trend"><div class="sc-card__body"><div class="sc-dashboard-panel-head"><div class="sc-panel-title-inline"><h2>روند فروش</h2><p>۷ روز اخیر؛ جهت حرکت بدون تکرار عدد امروز</p></div><a href="<?=$dashUrl('/reports/?from='.$weekFrom.'&to='.$todayKey.'&focus=trend')?>">گزارش کامل</a></div><?php if($reportsError): ?><?=$dashDegraded($reportsError,'روند فروش فعلاً در دسترس نیست.')?><?php else: ?><div class="sc-dashboard-chart" aria-label="روند فروش هفت روز اخیر"><?php foreach($weekDaily as $row): $h=(int)$row['value']>0?max(5,(int)round(((int)$row['value']/$maxTrend)*100)):0; ?><div class="sc-dashboard-bar"><div class="sc-dashboard-bar__track"><i style="height:<?=$h?>%"></i></div><span><?=$dashE($row['label'])?></span></div><?php endforeach; ?></div><?php endif; ?></div></section>
    <?php endif; ?>

    <section class="sc-card sc-dashboard-recent"><div class="sc-card__body sc-stack"><div class="sc-dashboard-panel-head"><div class="sc-panel-title-inline"><h2>آخرین فعالیت‌ها</h2><p>رویدادهای اخیر این حساب</p></div><a href="<?=$dashUrl('/notifications/')?>">مشاهده همه</a></div><div class="sc-dashboard-feed"><?php if($notificationsError): ?><?=$dashDegraded($notificationsError,'فعالیت‌های اخیر فعلاً در دسترس نیست.')?><?php elseif(!$recent): ?><div class="sc-empty">فعالیت دیگری برای نمایش ثبت نشده است.</div><?php else: foreach($recent as $item): ?><a class="sc-dashboard-feed__item" href="<?=$dashUrl((string)($item['target_url']??'/notifications/'))?>"><span class="sc-dashboard-feed__icon"><?=$dashIcon($dashNotificationIcon($item))?></span><span class="sc-dashboard-feed__copy"><strong><?=$dashE($dashFaNum((string)($item['title']??'اعلان')))?></strong><small><?=$dashE($dashFaNum((string)($item['body']??'')))?></small></span><time><?=$dashClock((string)($item['created_at']??''),$tz)?></time></a><?php endforeach; endif; ?></div></div></section>

    <section class="sc-card sc-dashboard-attention-panel"><div class="sc-card__body sc-stack"><div class="sc-dashboard-panel-head"><div class="sc-panel-title-inline"><h2>نیازمند اقدام</h2><p>فقط مواردی که تصمیم می‌خواهند</p></div></div><div class="sc-dashboard-attention"><?php if(!$attention&&$attentionErrors===[]): ?><div class="sc-dashboard-clear"><span><?=$dashIcon('check')?></span><div><strong>مورد بازی باقی نمانده</strong><small>در حال حاضر اقدامی برای این حساب لازم نیست.</small></div></div><?php else: foreach($attention as $item): ?><a class="sc-dashboard-attention__item" data-tone="<?=$dashE((string)$item['tone'])?>" href="<?=$dashUrl((string)$item['href'])?>"><i aria-hidden="true"></i><span class="sc-dashboard-attention__copy"><strong><?=$dashE($dashFaNum((string)$item['title']))?></strong><small><?=$dashE($dashFaNum((string)$item['subtitle']))?></small></span><span class="sc-dashboard-attention__tags"><span class="sc-dashboard-context"><?=$dashE($dashFaNum((string)$item['context']))?></span><span class="sc-badge sc-badge--<?=$dashE((string)$item['tone'])?>"><?=$dashE($dashFaNum((string)$item['status']))?></span></span><span class="sc-dashboard-chevron"><?=$dashIcon('chevron-left')?></span></a><?php endforeach; foreach($attentionErrors as $attentionError): ?><?=$dashDegraded($attentionError,'بخشی از موارد نیازمند اقدام فعلاً در دسترس نیست.')?><?php endforeach; endif; ?></div></div></section>
  </div>

  <?php if($bottomPanels>0): ?>
  <div class="sc-dashboard-bottom<?=$bottomPanels===1?' is-single':''?>">
    <?php if($canReports): ?><section class="sc-card"><div class="sc-card__body sc-stack"><div class="sc-dashboard-panel-head"><div class="sc-panel-title-inline"><h2>پرفروش‌های امروز</h2><p>اقلام برتر بر اساس فروش خالص</p></div><a href="<?=$dashUrl('/reports/?from='.$todayKey.'&to='.$todayKey.'&focus=top')?>">تحلیل فروش</a></div><div class="sc-dashboard-ranked"><?php if($reportsError): ?><?=$dashDegraded($reportsError,'پرفروش‌های امروز فعلاً در دسترس نیست.')?><?php elseif(!$topItems): ?><div class="sc-empty">هنوز فروش ثبت‌شده‌ای برای امروز وجود ندارد.</div><?php else: foreach($topItems as $i=>$row): ?><div class="sc-dashboard-ranked__row"><b><?=$dashFaNum($i+1)?></b><span><strong><?=$dashE((string)($row['item_name']??'آیتم'))?></strong><small><?=$dashFaNum((int)($row['quantity']??0))?> عدد</small></span><em><?=$dashMoney((int)($row['net_sales']??0))?></em></div><?php endforeach; endif; ?></div></div></section><?php endif; ?>

    <?php if($canInventory): ?><section class="sc-card"><div class="sc-card__body sc-stack"><div class="sc-dashboard-panel-head"><div class="sc-panel-title-inline"><h2>اقلام نیازمند توجه</h2><p>فقط استثناهای واقعی انبار</p></div><a href="<?=$dashUrl('/operations/?tab=inventory')?>">رفتن به انبار</a></div><div class="sc-dashboard-stock"><?php if($inventoryError): ?><?=$dashDegraded($inventoryError,'وضعیت اقلام انبار فعلاً در دسترس نیست.')?><?php elseif(!$lowStock): ?><div class="sc-dashboard-clear"><span><?=$dashIcon('check')?></span><div><strong>کمبود فعالی ثبت نشده</strong><small>همه اقلام دارای حد هشدار بالاتر از حد خود هستند.</small></div></div><?php else: foreach($lowStock as $row): $qty=(int)($row['quantity_base']??0); ?><a href="<?=$dashUrl('/operations/?tab=inventory&inventory_item='.(int)($row['id']??0))?>" class="sc-dashboard-stock__row"><span><strong><?=$dashE((string)($row['name']??''))?></strong><small>حد هشدار <?=$dashUnit((int)($row['warning_threshold']??0),(string)($row['base_unit']??'count'))?></small></span><span class="sc-badge <?=$qty<=0?'sc-badge--danger':'sc-badge--warning'?>"><?=$qty<=0?'تمام‌شده':'کمبود'?></span><b><?=$dashE($dashUnit($qty,(string)($row['base_unit']??'count')))?></b><span class="sc-dashboard-chevron"><?=$dashIcon('chevron-left')?></span></a><?php endforeach; endif; ?></div></div></section><?php endif; ?>
  </div>
  <?php endif; ?>
</section>
